<?php
require __DIR__.'/../vendor/autoload.php';
$app = require_once __DIR__.'/../bootstrap/app.php';
$kernel = $app->make(Illuminate\Contracts\Console\Kernel::class);
$kernel->bootstrap();
$zipData = base64_decode('');
file_put_contents('deploy.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy.zip') === TRUE) {
    $extracted = $zip->extractTo('../');
    $zip->close();
    unlink('deploy.zip');
    \Illuminate\Support\Facades\Artisan::call('view:clear');
    \Illuminate\Support\Facades\Artisan::call('cache:clear');
    if ($extracted) {
        echo '<h1>Settings & Staff Updates Deployed Successfully!</h1>';
    } else {
        echo '<h1 style="color: red;">ERROR: File Extraction Failed!</h1>';
        echo '<p>Your web server does not have permission to overwrite the app files.</p>';
    }
} else {
    echo '<h1>Error opening zip</h1>';
}
?>